import React, { useState, useEffect, useRef } from 'react';

// Create the App component here
const App = () => {
  // Initialize searchTerm state here
  const [searchTerm, setSearchTerm] = useState('');

  // Initialize debouncedTerm state here
  const [debouncedTerm, setDebouncedTerm] = useState('');

  // Create timeoutRef here
  const timeoutRef = useRef<NodeJS.Timeout | null>(null);

  // Add useEffect for debounce logic here
  useEffect(() => {
    if (timeoutRef.current) {
      clearTimeout(timeoutRef.current);
    }
    timeoutRef.current = setTimeout(() => {
      setDebouncedTerm(searchTerm);
    }, 500);
    return () => {
      if (timeoutRef.current) {
        clearTimeout(timeoutRef.current);
      }
    };
  }, [searchTerm]);

  // Create handleSearchChange function here
  const handleSearchChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    setSearchTerm(e.target.value);
  };

  return (
    <div>
      {/* Add your search input element here */}
      <input
        type="text"
        value={searchTerm}
        onChange={handleSearchChange}
        placeholder="Type to search..."
      />

    </div>
  );
};
